mapper.select:
SELECT A.ATTENDANCE_ID AS attendanceId, A.STUDENT_ID AS studentId, S.EDU_ID AS eduId, DATE_FORMAT(A.ATTEND_DATE, '%Y-%m-%d') AS attendDate, A.STATUS AS status, A.MESSAGE AS message, DATE_FORMAT(A.CREATED_AT, '%Y-%m-%d %H:%i:%S') AS createdAt, DATE_FORMAT(A.UPDATED_AT, '%Y-%m-%d %H:%i:%S') AS updatedAt FROM ATTENDANCE A LEFT JOIN STUDENTS S ON A.STUDENT_ID = S.STUDENT_ID
S.DEL_YN = 'N'
AND A.STUDENT_ID = #{studentId}
AND S.EDU_ID = #{eduId}
AND A.ATTEND_DATE = #{attendDate}
AND A.STATUS = #{status}

mapper.update:
		UPDATE ATTENDANCE


					MESSAGE=#{message},


					STATUS=#{status},

				UPDATED_AT=NOW()

 		WHERE STUDENT_ID = #{studentId}
 			AND ATTEND_DATE = #{attendDate}
